class PrepareChunksThread:
    def __init__(self, maxsize: int):
        self._to_download_queue = multiprocessing.Queue(maxsize=maxsize)

    def download(self, chunk_indexes: List[int]) -> None:
        """
        Enqueues the given chunk indexes to the _to_download_queue.

        :param chunk_indexes: List[int]. A list of chunk indexes.
        """
        _DEFAULT_TIMEOUT = 10

        for chunk_index in chunk_indexes:
            try:
                self._to_download_queue.put(chunk_index, block=True, timeout=_DEFAULT_TIMEOUT)
            except (multiprocessing.Queue.Full, multiprocessing.TimeoutError):
                print(f"Queue is full or timed out. Dropping chunk index: {chunk_index}")
            except TypeError:
                raise TypeError("Chunk index is not serializable")
