        min_clauses = int(spec_parts[0].strip())

        # parse the second part of the specification (maximum number of clauses that can match)
        max_clauses = int(spec_parts[1].strip())

        # compare num_clauses with min_clauses
        if num_clauses <= min_clauses:
            return min_clauses
        else:
            # recursively call parse_min_should_match with max_clauses
